package com.hospital.system.repository; import com.hospital.system.model.Payment; import java.math.*; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository;
@Repository public class PaymentRepository { private final JdbcTemplate db; public PaymentRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Payment> m=(r,n)->{Payment p=new Payment();p.paymentId=r.getLong("payment_id");p.billId=r.getLong("bill_id");p.paymentDate=r.getTimestamp("payment_date").toLocalDateTime();p.amount=r.getBigDecimal("amount");p.paymentMethod=r.getString("payment_method");p.referenceNo=r.getString("reference_no");return p;}; public List<Payment> all(Long bill){return db.query("SELECT * FROM payment WHERE bill_id=? ORDER BY payment_id DESC",m,bill);} public BigDecimal paid(Long bill){return db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM payment WHERE bill_id=?",BigDecimal.class,bill);} public int add(Long bill,Payment p){return db.update("INSERT INTO payment(bill_id,amount,payment_method,reference_no) VALUES(?,?,?,?)",bill,p.amount,p.paymentMethod,p.referenceNo);} }
